fun {α} F noise {stage} current =>
  have hOldNodup := ⋯;
  have hTarget := ⋯;
  let split := Classical.choice.{1} ⋯;
  let newValue :=
    GenLimit.ParetoGeneration.noisyInsertionScore.{u_1} F noise
      (GenLimit.ParetoGeneration.NoisyInsertionSplit.left.{u_1} split) stage;
  let newWitnessSet :=
    GenLimit.ParetoGeneration.totalNoisyStepSample.{u_1} F noise
      (GenLimit.ParetoGeneration.noisyInsertionScope (GenLimit.ParetoGeneration.NoisyInsertionSplit.left.{u_1} split)
        stage)
      stage;
  let newWitness :=
    GenLimit.ParetoGeneration.totalNoisyStepWitness.{u_1} F noise
      (GenLimit.ParetoGeneration.noisyInsertionScope (GenLimit.ParetoGeneration.NoisyInsertionSplit.left.{u_1} split)
        stage)
      stage;
  let nextComplexity :=
    GenLimit.ParetoGeneration.setComplexity (GenLimit.ParetoGeneration.NoisyProcedureStage.complexity.{u_1} current)
      stage newValue;
  let nextWitnessSet :=
    GenLimit.ParetoGeneration.setNoisyWitnessSet.{u_1}
      (GenLimit.ParetoGeneration.NoisyProcedureStage.witnessSet.{u_1} current) stage newWitnessSet;
  let nextWitness :=
    GenLimit.ParetoGeneration.setWitness (GenLimit.ParetoGeneration.NoisyProcedureStage.witness.{u_1} current) stage
      newWitness;
  GenLimit.ParetoGeneration.NoisyProcedureStage.mk.{u_1}
    (HAppend.hAppend.{0, 0, 0} (GenLimit.ParetoGeneration.NoisyInsertionSplit.left.{u_1} split)
      (List.cons.{0} stage (GenLimit.ParetoGeneration.NoisyInsertionSplit.right.{u_1} split)))
    nextComplexity nextWitnessSet nextWitness ⋯ ⋯ ⋯ ⋯ ⋯ ⋯ ⋯

