fun {α} [Infinite.{u_1 + 1} α] F noise f x xs =>
  let sample := GenLimit.Generic.sequenceSample.{u_1} xs;
  let selected :=
    GenLimit.ParetoGeneration.noisyGreedyScan.{u_1} F noise sample EmptyCollection.emptyCollection.{0}
      (GenLimit.ParetoGeneration.noisySchedulerScanOrder.{u_1} F noise f (Finset.card.{u_1} sample));
  GenLimit.Support.freshFromInfinite.{u_1} (GenLimit.ParetoGeneration.indexedIntersection.{u_1} F selected) ⋯ sample

