fun {α} [Infinite.{u_1 + 1} α] F f x xs =>
  let sample := GenLimit.Generic.sequenceSample.{u_1} xs;
  let selected :=
    GenLimit.ParetoGeneration.greedyListScan.{u_1} F sample EmptyCollection.emptyCollection.{0}
      (GenLimit.ParetoGeneration.schedulerScanOrder.{u_1} F f (Finset.card.{u_1} sample));
  GenLimit.Support.freshFromInfinite.{u_1} (GenLimit.ParetoGeneration.indexedIntersection.{u_1} F selected) ⋯ sample

fun {α} F noise scopeSet target =>
  if hExists :
      ∃ sample, GenLimit.ParetoGeneration.NoisyProcedureSampleCandidate.{u_1} F noise scopeSet target sample then
    Classical.choose.{u_1 + 1} ⋯
  else EmptyCollection.emptyCollection.{u_1}

fun {α} F noise scopeSet target =>
  if hCandidate :
      GenLimit.ParetoGeneration.NoisyProcedureSampleCandidate.{u_1} F noise scopeSet target
        (GenLimit.ParetoGeneration.totalNoisyStepSample.{u_1} F noise scopeSet target) then
    Classical.choose.{1} hCandidate
  else EmptyCollection.emptyCollection.{0}

